{name:'Emun',maker:'TECHVIBE HOME',cat:'Để bàn',lead:'Học tiếng Anh cùng người bạn robot.',desc:'Robot phục vụ trải nghiệm học tiếng Anh, giao tiếp và khám phá kiến thức theo định hướng giáo dục.',tags:['Học tiếng Anh','Giáo dục','Tương tác'],tone:'#edf1e6',icon:'✦'},
{name:'Cozmo',maker:'ANKI',cat:'Giáo dục',lead:'Học lập trình qua trò chơi.',desc:'Robot tương tác bằng bánh xích và các trò chơi, phù hợp khám phá robotics và lập trình.',tags:['Học lập trình','Trò chơi','Robot bánh xích'],tone:'#edf2f6',icon:'🎮'},
{name:'Looi',maker:'TANGIBLE FUTURE',cat:'Để bàn',lead:'Biến điện thoại thành người bạn robot.',desc:'Robot đồng hành sử dụng điện thoại làm gương mặt và tương tác với người dùng.',tags:['Kết hợp điện thoại','Biểu cảm','Tương tác'],tone:'#f0e9f5',icon:'📱'}
