function setupScrollTop(){const b=document.querySelector('#scroll-to-top');if(!b)return;const refresh=()=>b.classList.toggle('visible',window.scrollY>300);window.removeEventListener('scroll',window.__techvibeScrollHandler);window.__techvibeScrollHandler=refresh;window.addEventListener('scroll',refresh,{passive:true});b.onclick=()=>window.scrollTo({top:0,behavior:'smooth'});refresh()}

function setupContactWidget(){const w=document.querySelector('#contact-float');if(!w)return;const b=w.querySelector('.contact-toggle'),o=w.querySelector('.contact-options');b.onclick=()=>{o.hidden=!o.hidden;b.setAttribute('aria-expanded',String(!o.hidden))};document.addEventListener('click',e=>{if(!w.contains(e.target)){o.hidden=true;b.setAttribute('aria-expanded','false')}},{once:false})}

function setupMobileMenu(){
 const toggle=document.querySelector('#mobile-menu-toggle'),links=document.querySelector('#site-links'),backdrop=document.querySelector('#mobile-drawer-backdrop'),closeButton=document.querySelector('#drawer-close');
 if(!toggle||!links||!backdrop)return;
 const openDrawer=()=>{links.classList.add('mobile-open');backdrop.hidden=false;requestAnimationFrame(()=>backdrop.classList.add('visible'));toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Đóng menu');document.body.classList.add('drawer-open');closeButton?.focus()};
 const closeDrawer=()=>{links.classList.remove('mobile-open');backdrop.classList.remove('visible');backdrop.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Mở menu');document.body.classList.remove('drawer-open')};
 toggle.onclick=()=>links.classList.contains('mobile-open')?closeDrawer():openDrawer();
 if(closeButton)closeButton.onclick=closeDrawer;
 backdrop.onclick=closeDrawer;
 links.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeDrawer));
 links.onkeydown=e=>{if(e.key==='Escape'){closeDrawer();toggle.focus();return}if(e.key!=='Tab'||!links.classList.contains('mobile-open'))return;const focusable=[...links.querySelectorAll('a,button,input,select')].filter(el=>!el.disabled&&el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};
}
function setupHeaderCart(){const b=document.querySelector('#header-cart');if(!b)return;b.onclick=()=>{if(location.pathname!=='/'&&location.pathname!==''){location.href='/#shop';return}if(window.TechShop?.openCart)window.TechShop.openCart();else location.hash='shop'};window.TechShop?.updateCartBadge?.()}


function setupLanguageSwitcher(){const trigger=document.querySelector('#language-trigger'),menu=document.querySelector('#language-menu');if(!trigger||!menu)return;trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden))};menu.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{TechVibeI18n.set(b.dataset.lang);menu.hidden=true;trigger.setAttribute('aria-expanded','false')});document.addEventListener('click',e=>{if(!e.target.closest('.language-switch')){menu.hidden=true;trigger.setAttribute('aria-expanded','false')}});TechVibeI18n.apply()}

// Bootstrap after all lexical declarations are initialized.
// Client-side navigation: keep the document, cart state and header mounted.
let navigationVersion=0;
async function route(){
 const current=++navigationVersion;
 const path=location.pathname;
 const render=path.startsWith('/admin')||path.startsWith('/quan-ly')?admin:
 path.startsWith('/robot/')?robotDetail:
 path==='/compare'?()=>comparePage(shell,api):
 path==='/track'?()=>trackPage(shell,api):
 path==='/warranty'?()=>warrantyPage(shell):
 path==='/lab'?()=>labPage(shell):home;
 try{await render();if(current!==navigationVersion)return;
  const target=location.hash&&document.getElementById(decodeURIComponent(location.hash.slice(1)));
  if(target)target.scrollIntoView({behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});
 }catch(e){if(current===navigationVersion)shell('<main class="section wrap"><p class="error">'+esc(e.message)+'</p></main>')}
}
document.addEventListener('click',event=>{
 if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
 const a=event.target.closest('a[href]');if(!a||a.target||a.hasAttribute('download'))return;
 const url=new URL(a.href,location.href);if(url.origin!==location.origin||!['http:','https:'].includes(url.protocol))return;
 if(url.pathname===location.pathname&&url.search===location.search&&url.hash){return}
 event.preventDefault();history.pushState({},'',url.pathname+url.search+url.hash);void route();
});
window.addEventListener('popstate',()=>{void route()});
void route();
